mapper.select:
SELECT 
FROM cases c INNER JOIN reporters r ON r.id = c.reporter_id
WHERE c.id = #{id}

mapper.update:
UPDATE reporters
SET name = #{reporterName}, phone = #{reporterPhone}, email = #{reporterEmail},
    relation = #{reporterRelation}
WHERE id = #{reporterId}

UPDATE cases
SET status = #{status}, closed_at = #{closedAt}, updated_at = UTC_TIMESTAMP(6)
WHERE id = #{id}

UPDATE cases
SET photo_s3_key = #{photoS3Key}, updated_at = UTC_TIMESTAMP(6)
WHERE id = #{id}
